INSERT INTO projects (id, sort_order, title, eyebrow, summary, story_html, role, year, stack_json, signal, accent, category, status, highlights_json, scope, ownership_json, systems_json, note, source_label, source_url, published, featured, version) VALUES ('ignite-dialogue', '0', 'Ignite Dialogue', 'Enterprise conversation engine', 'A highly configurable decision-tree platform used by major financial institutions to guide customers toward the right products.', '', 'Lead Backend Engineer', '2020—Now', '["Node.js","React","AWS","MongoDB"]', 'DLG', 'acid', 'Enterprise', 'Production system', '["Designed self-service integrations with self-defining models and generated UI.","Scaled infrastructure across AWS, Cloudflare, and multiple Mongo clusters.","Built automated delivery with CloudFormation, Service Catalog, and CodePipeline."]', 'A modernization effort for a configurable guided-conversation product used in financial-services workflows.', '["Reworked the aging decision-tree foundation for cloud-scale operation.","Built an integration layer where models describe themselves and drive generated configuration UI.","Supported enterprise theming, customer customization, guide publishing, and a staged MongoDB data migration."]', '["Node.js services with a React application and legacy Scala","AWS delivery and publishing workflows","Cloudflare domains, observability, and separated MongoDB clusters"]', 'The current product page describes the broader platform; this record focuses on the architecture and delivery work listed in my résumé.', 'View current Ignite Dialogue context', 'https://ignitesales.com/solutions/', 1, 1, 1);
INSERT INTO projects (id, sort_order, title, eyebrow, summary, story_html, role, year, stack_json, signal, accent, category, status, highlights_json, scope, ownership_json, systems_json, note, source_label, source_url, published, featured, version) VALUES ('ignite-ai', '1', 'Ignite AI', 'Human-in-the-middle automation', 'A set of web and desktop tools that use language models, OCR, decision trees, and agents to accelerate client onboarding.', '', 'Lead Backend Engineer', 'Current', '["OpenAI","Node.js","React","Electron"]', 'AIX', 'amber', 'AI + Automation', 'Production tools', '["Designed multi-step workflows that keep people in control of AI output.","Combined LLMs, task agents, OCR, Puppeteer, and existing decision systems."]', 'A collection of operator-facing web and desktop tools for creating guides and collecting onboarding information with reviewable AI assistance.', '["Designed human-in-the-middle flows so people can inspect and guide generated output.","Connected language models, document OCR, decision trees, and task agents into a multi-step onboarding process.","Built across browser and Electron surfaces rather than treating AI as a standalone chat feature."]', '["Node.js and React","OpenAI API, task agents, and OCR","Electron and browser automation with Puppeteer"]', 'This page intentionally describes the workflow pattern rather than customer data, prompts, or internal onboarding operations.', NULL, NULL, 1, 1, 1);
INSERT INTO projects (id, sort_order, title, eyebrow, summary, story_html, role, year, stack_json, signal, accent, category, status, highlights_json, scope, ownership_json, systems_json, note, source_label, source_url, published, featured, version) VALUES ('tradelab', '2', 'TradeLab', 'Automated market strategy lab', 'A no-code trading automation platform for combining market-data pipes, webhooks, strategy rules, and AI-assisted configuration.', '', 'Founder · Product Engineer', '2021—Now', '["TypeScript","Angular","GCP","Firebase"]', 'TDL', 'ice', 'AI + Automation', 'Founder product', '["Created easy and advanced no-code strategy builders.","Built synchronous worker pools for time-sensitive market events.","Added an LLM conversation layer for authoring strategy rules."]', 'A founder-built strategy automation product that turns incoming market signals and webhooks into configurable rules and dashboards.', '["Designed separate easy and advanced rule-building modes for different levels of technical comfort.","Implemented synchronous worker pools for time-sensitive event processing.","Created an AI-assisted authoring experience and TradingView-connected workflow for building strategy rules."]', '["Angular 11, TypeScript, and Node.js","Firebase Auth, Firestore, and Google Cloud CI/CD","Webhooks, market-data pipes, worker pools, and custom dashboards"]', 'The product is software for configuring workflows; it is not financial advice or a promise of market performance.', NULL, NULL, 1, 1, 1);
INSERT INTO project_media (id, project_id, kind, url, caption, alt_text, sort_order, autoplay, preload) VALUES ('tradelab-video', 'tradelab', 'video', 'https://www.youtube.com/watch?v=c5mejriB_6U', 'Product walkthrough', '', 0, 1, 'metadata');
INSERT INTO projects (id, sort_order, title, eyebrow, summary, story_html, role, year, stack_json, signal, accent, category, status, highlights_json, scope, ownership_json, systems_json, note, source_label, source_url, published, featured, version) VALUES ('stream-elixir', '3', 'Stream Elixir', 'Automation for live creators', 'A cross-platform desktop product that automated repetitive audience-growth workflows across Twitch and social platforms.', '', 'Founder · Product Engineer', '2018—2021', '["Electron","Angular","Express","MongoDB"]', 'STR', 'acid', 'SaaS', 'Shipped desktop app', '["Released for macOS, Windows, and Linux.","Integrated Twitch, Facebook, Twitter, and YouTube APIs."]', 'A cross-platform desktop application for automating repetitive community and audience-management routines for live creators.', '["Took the product from a 2018 Electron release through multi-platform desktop delivery.","Integrated platform APIs for Twitch, Facebook, Twitter, and YouTube workflows.","Built the product around common creator routines rather than a single-channel dashboard."]', '["Electron desktop shell for macOS, Windows, and Linux","Angular 9, Express, and MongoDB","Third-party social and livestream platform APIs"]', NULL, NULL, NULL, 1, 1, 1);
INSERT INTO project_media (id, project_id, kind, url, caption, alt_text, sort_order, autoplay, preload) VALUES ('stream-elixir-video', 'stream-elixir', 'video', 'https://www.youtube.com/watch?v=pK2DNWlO8j4', 'Product walkthrough', '', 0, 1, 'metadata');
