INSERT INTO projects (id, sort_order, title, eyebrow, summary, story_html, role, year, stack_json, signal, accent, category, status, highlights_json, scope, ownership_json, systems_json, note, source_label, source_url, published, featured, version) VALUES ('ezforms', '4', 'EZFORMS', 'Enterprise document platform', 'A complete digital document system spanning a web-based drag-and-drop builder, administration tools, mobile execution, reporting, and an SDK.', '', 'Product Lead · Lead Engineer', '2013—2020', '["Angular","Node.js","MongoDB","Ionic"]', 'EZF', 'amber', 'Enterprise', 'Production platform', '["Designed and iterated on the core drag-and-drop document builder.","Delivered native and hybrid iOS and Android form applications.","Used by FedEx, Taco Bueno, Dave & Buster’s, Yellow Tail Wines, Boy Scouts of America, and city municipalities, as listed in my résumé."]', 'A full document-execution platform spanning a web builder, admin tools, mobile apps, reporting, and an integration SDK.', '["Led design, implementation, testing, and scaling work across the front and back end.","Designed and iterated on the drag-and-drop builder and the supporting administration portal.","Shipped native and hybrid mobile execution experiences and helped shape data models for durable reporting."]', '["Angular 9, Node.js, MongoDB, and Ionic","AndroidX and Jetpack alongside iOS delivery","PDF rendering pipeline and developer SDK"]', 'Named organizations are those listed in my résumé; this archive does not expose their forms, data, or internal deployments.', NULL, NULL, 1, 0, 1);
INSERT INTO project_media (id, project_id, kind, url, caption, alt_text, sort_order, autoplay, preload) VALUES ('ezforms-image-1', 'ezforms', 'image', '/projects/ezforms/dashboard.webp', 'EZFORMS — scheduled forms and daily task dashboard', 'EZFORMS — scheduled forms and daily task dashboard', 0, 0, 'auto');
