INSERT INTO project_media (id, project_id, kind, url, caption, alt_text, sort_order, autoplay, preload) VALUES ('ezforms-image-3', 'ezforms', 'image', '/projects/ezforms/logo.webp', 'EZFORMS — Checklist & Audit Compliance', 'EZFORMS — Checklist & Audit Compliance', 2, 0, 'metadata');
INSERT INTO projects (id, sort_order, title, eyebrow, summary, story_html, role, year, stack_json, signal, accent, category, status, highlights_json, scope, ownership_json, systems_json, note, source_label, source_url, published, featured, version) VALUES ('eternus-tools', '5', 'Eternus Engine Tools', 'Live 3D game production suite', 'Eight connected tools for editing assets, particles, UI, atlases, terrain, and character animation against a live C++ game engine.', '', 'Lead of Tool Development', '2015—2017', '["Electron","WebGL","Angular","C++"]', 'ETN', 'ice', 'Creative Tools', 'Shipped internal suite', '["Led a three-person full-stack tools team.","Designed caching to minimize expensive Electron remote-process calls.","Rendered the C++ engine directly into a WebGL canvas at high frame rates."]', 'An eight-tool production suite for editing live game assets and data against an in-house C++ engine.', '["Led a three-person full-stack tools team while also shipping tools and prototypes directly.","Developed a cache-conscious bridge between Electron processes and the live engine.","Helped evolve the tooling UI from Angular 1 to Angular 5 and built custom WebGL graphing and TypeScript scripting directives."]', '["Electron, Angular, WebGL, and TypeScript","Direct engine rendering in a WebGL canvas","Asset, particle, UI, atlas, terrain, and animation/node-graph editors"]', 'This is a retrospective of internal production tooling; implementation details are intentionally summarized.', NULL, NULL, 1, 0, 1);
INSERT INTO projects (id, sort_order, title, eyebrow, summary, story_html, role, year, stack_json, signal, accent, category, status, highlights_json, scope, ownership_json, systems_json, note, source_label, source_url, published, featured, version) VALUES ('tumor-identifier', '6', 'Tumor Identifier', 'Medical imaging prototype', 'A Baylor Medical Center application that identified tumors across biopsy scans and reconstructed the result inside a 3D model.', '', 'Creative Technologist', 'R&D archive', '["TensorFlow.js","WebGL","Node.js"]', 'TMR', 'acid', 'AI + Automation', 'Research prototype', '["Matched 2D scan regions to a three-dimensional biopsy model.","Generated an outlined 3D representation of detected tumor tissue."]', 'An R&D visualization prototype for aligning scan slices with a three-dimensional biopsy model and reconstructing a marked region in context.', '["Worked with 3D and 2D biopsy scan inputs as part of the prototype workflow.","Mapped outlined regions across slices into a reconstructed 3D representation.","Built an explorable browser visualization to communicate the scan-to-model process."]', '["WebGL, Node.js, and custom browser JavaScript","TensorFlow.js listed in the original project stack","Slice alignment, contours, and 3D reconstruction"]', 'The interactive demo on this site uses synthetic geometry only. It is a historical visualization prototype, not a diagnostic tool or clinical advice.', NULL, NULL, 1, 0, 1);
INSERT INTO projects (id, sort_order, title, eyebrow, summary, story_html, role, year, stack_json, signal, accent, category, status, highlights_json, scope, ownership_json, systems_json, note, source_label, source_url, published, featured, version) VALUES ('ziprad', '7', 'ZipRad', 'EHR-to-imaging automation', 'A medical workflow that transformed patient data from EHR systems into imaging-center orders for procedures such as X-rays and CAT scans.', '', 'Lead Engineer', 'Product archive', '["Angular","Node.js","Kotlin","OCR"]', 'ZIP', 'amber', 'Enterprise', 'Production application', '["Used a custom OCR print driver and PDF generation pipeline.","Included a privately distributed native Android application."]', 'A healthcare operations workflow for translating EHR-originated information into imaging-center orders without requiring a manual re-entry step.', '["Built the order-generation workflow around a custom OCR print driver and PDF generation.","Worked across the Angular web application, Node/Mongo back end, and a privately distributed Kotlin Android app.","Focused the product on bridging systems that did not share a direct connection."]', '["Angular 8, Node.js, and MongoDB","Custom OCR print driver and PDF pipeline","Native Kotlin Android client"]', 'The work is described at a systems level to avoid exposing health data, integrations, or operational details.', 'View ZipData’s current product context', 'https://www.zipdatasolutions.com/', 1, 0, 1);
INSERT INTO project_media (id, project_id, kind, url, caption, alt_text, sort_order, autoplay, preload) VALUES ('ziprad-video', 'ziprad', 'video', 'https://www.youtube.com/watch?v=fXm5drN--C0', 'Product walkthrough', '', 0, 1, 'metadata');
INSERT INTO projects (id, sort_order, title, eyebrow, summary, story_html, role, year, stack_json, signal, accent, category, status, highlights_json, scope, ownership_json, systems_json, note, source_label, source_url, published, featured, version) VALUES ('traxo', '8', 'Traxo', 'Travel organizer', 'Native mobile applications that organized itineraries and reward programs, with an Android Wear companion for upcoming travel.', '', 'Mobile Engineer', 'Mobile archive', '["Kotlin","Java","iOS","Android Wear"]', 'TRX', 'ice', 'Mobile', 'Shipped mobile apps', '["Delivered native Android and iOS applications.","Migrated Android from the Support Library to AndroidX and Jetpack."]', 'Native mobile work for a travel product focused on keeping itineraries and reward information together, including a wearable companion.', '["Delivered native Android and iOS applications for travel organization.","Built an Android Wear component for upcoming travel appointments.","Modernized the Android implementation from the Support Library to AndroidX and Jetpack during a rewrite."]', '["Kotlin plus a proprietary Java SDK on Android","Native iOS and Android delivery","Android Wear, AndroidX, and Jetpack"]', 'Traxo has since evolved into a broader corporate-travel platform; this page documents the earlier mobile product work in the archive.', 'View current Traxo context', 'https://www.traxo.com/', 1, 0, 1);
