INSERT INTO projects (id, sort_order, title, eyebrow, summary, story_html, role, year, stack_json, signal, accent, category, status, highlights_json, scope, ownership_json, systems_json, note, source_label, source_url, published, featured, version) VALUES ('trails-end', '9', 'Trails End: Show N’ Sell', 'Field sales at enormous scale', 'A popcorn fundraising app for Boy Scouts of America scouts and leaders to schedule sales events and take payments in the field.', '', 'Mobile Product Engineer', 'Mobile archive', '["Ionic","Kotlin","Stripe","Google Maps"]', 'BSA', 'acid', 'Mobile', 'Shipped mobile apps', '["Released on Android and iOS.","Used native Kotlin views for security-sensitive payment surfaces.","Supported a large Square integration serving millions of users."]', 'A field-sales companion for popcorn fundraising events, allowing scouts and leaders to coordinate selling and accept card payments.', '["Shipped hybrid iOS and Android applications with Ionic 3.","Integrated Stripe and Google Maps for sales and event workflows.","Used native Kotlin views for security-sensitive payment surfaces and supported a large Square integration."]', '["Ionic 3 for iOS and Android","Kotlin, MVVM, AndroidX, and Jetpack","Stripe, Google Maps SDK, and Square integration"]', 'This is historical product work. Current Trails End features and branding may differ from the version represented here.', NULL, NULL, 1, 0, 1);
INSERT INTO project_media (id, project_id, kind, url, caption, alt_text, sort_order, autoplay, preload) VALUES ('trails-end-image-1', 'trails-end', 'image', '/projects/trails-end/dashboard.webp', 'Scout sales dashboard', 'Scout sales dashboard', 0, 0, 'auto');
INSERT INTO project_media (id, project_id, kind, url, caption, alt_text, sort_order, autoplay, preload) VALUES ('trails-end-image-2', 'trails-end', 'image', '/projects/trails-end/overview.webp', 'Archived Trail’s End app promotion and online sales workflow', 'Archived Trail’s End app promotion and online sales workflow', 1, 0, 'metadata');
INSERT INTO projects (id, sort_order, title, eyebrow, summary, story_html, role, year, stack_json, signal, accent, category, status, highlights_json, scope, ownership_json, systems_json, note, source_label, source_url, published, featured, version) VALUES ('callsmart', '10', 'CallSmart', 'Callahan Roach · later became ProfitRhino', 'A cross-platform tool for repair professionals to manage customers and equipment, create orders, and accept payment on site.', '', 'Mobile Engineer', 'Mobile archive', '["PhoneGap","Cordova","Kendo UI"]', 'POS', 'amber', 'Mobile', 'Shipped mobile apps', '["Built Android and iOS applications around an MVVM architecture.","Designed for plumbers, HVAC teams, and pool-service professionals."]', 'A mobile point-of-sale and field-service tool for repair teams managing customer details, equipment, orders, and payments on site.', '["Built Android and iOS experiences using a cross-platform PhoneGap/Cordova stack.","Structured the app around Kendo UI and an MVVM architecture.","Designed for practical field workflows across plumbing, HVAC, and pool-service teams."]', '["PhoneGap and Cordova","Kendo UI with MVVM","Cross-platform Android and iOS delivery"]', 'CallSmart later became ProfitRhino; this record documents the earlier mobile product rather than the current company product.', NULL, NULL, 1, 0, 1);
INSERT INTO projects (id, sort_order, title, eyebrow, summary, story_html, role, year, stack_json, signal, accent, category, status, highlights_json, scope, ownership_json, systems_json, note, source_label, source_url, published, featured, version) VALUES ('foodtronix-mobile-pos', '11', 'FoodTronix Mobile POS', 'Tableside restaurant ordering', 'An Android tablet ordering system that let restaurant staff take orders tableside and route them directly to kitchen printers.', '', 'Lead Developer', '2011—2012', '["Android","MSSQL","POS"]', 'FDP', 'ice', 'Mobile', 'Production application', '["Integrated with an established restaurant-management suite.","Worked across receipt printers, payment gateways, tax, and discount logic."]', 'The first mobile ordering experience in a restaurant-management environment, built for tablet-based tableside service.', '["Built an Android tablet workflow for taking orders at the table and routing them to kitchen printers.","Integrated with a broader restaurant-management suite rather than creating a disconnected ordering app.","Worked in the wider POS environment of ticket logic, payments, printers, taxes, and discounts."]', '["Native Android tablet client","MSSQL-connected restaurant-management suite","Kitchen and receipt printer, payment, tax, and discount integrations"]', 'The current FoodTronix offering has evolved; this project reflects the 2011–2012 mobile POS work.', 'View current FoodTronix context', 'https://www.foodtronix.com/', 1, 0, 1);
INSERT INTO project_media (id, project_id, kind, url, caption, alt_text, sort_order, autoplay, preload) VALUES ('foodtronix-mobile-pos-image-1', 'foodtronix-mobile-pos', 'image', '/projects/foodtronix/hardware.webp', 'FoodTronix product and point-of-sale hardware', 'FoodTronix product and point-of-sale hardware', 0, 0, 'auto');
INSERT INTO projects (id, sort_order, title, eyebrow, summary, story_html, role, year, stack_json, signal, accent, category, status, highlights_json, scope, ownership_json, systems_json, note, source_label, source_url, published, featured, version) VALUES ('tug', '12', 'TUG v1', 'Smooth voxel sandbox', 'A 3D sandbox game created with the Nerd Kingdom team, backed by a TypeScript scripting system and a custom production toolchain.', '', 'Tools Lead · Engineer', '2015—2017', '["TypeScript","C++","Game Tools"]', 'TUG', 'acid', 'Games', 'Shipped game project', '["Created and maintained parts of the TypeScript scripting system.","Built the engine-tool suite used by the production team."]', 'A smooth-voxel sandbox game created with the Nerd Kingdom team, paired with the production tooling needed to build it.', '["Created and maintained portions of the TypeScript scripting system.","Built the game-engine tools that supported the production team.","Worked across a Windows game project and an in-house engine/toolchain."]', '["TypeScript scripting","Custom C++ game engine and production tooling","3D smooth-voxel sandbox gameplay"]', 'This archive records my tools and scripting contribution, not sole authorship of the game.', NULL, NULL, 1, 0, 1);
INSERT INTO projects (id, sort_order, title, eyebrow, summary, story_html, role, year, stack_json, signal, accent, category, status, highlights_json, scope, ownership_json, systems_json, note, source_label, source_url, published, featured, version) VALUES ('daho', '13', 'DAHO', 'Strategy puzzle game', 'A board-game-inspired number puzzle with challenge modes and custom-written AI, prototyped natively and rebuilt for production.', '', 'Game Designer · Engineer', 'Game archive', '["Ionic","Angular","Android"]', 'DAH', 'amber', 'Games', 'Shipped game', '["Built the original proof of concept in native Android.","Rebuilt the production version with Ionic and Angular."]', 'A number-based strategy puzzle inspired by the territory and planning dynamics of Go, built first as a native proof of concept and then as a production game.', '["Prototyped the original game in native Android.","Rebuilt the release version with Ionic 4 and Angular 7.","Designed challenge modes and wrote the game’s custom AI behavior."]', '["Native Android proof of concept","Ionic 4 and Angular 7 production build","Custom game AI and challenge-mode logic"]', NULL, NULL, NULL, 1, 0, 1);
INSERT INTO projects (id, sort_order, title, eyebrow, summary, story_html, role, year, stack_json, signal, accent, category, status, highlights_json, scope, ownership_json, systems_json, note, source_label, source_url, published, featured, version) VALUES ('jumpstart', '14', 'JumpStart', 'Photoshop-to-iPhone workflow', 'A Photoshop plugin that sliced UI layers and programmatically transformed them into the foundation of an iPhone application.', '', 'Creative Developer', 'Tool archive', '["JavaScript","Adobe Photoshop"]', 'JMP', 'ice', 'Creative Tools', 'Shipped plugin', '["Automated repetitive design-to-development handoff work.","Built in pure JavaScript using Adobe’s Photoshop framework."]', 'A Photoshop Cloud Edition plugin intended to reduce design-to-development repetition for early iPhone app workflows.', '["Automated slicing of UI layers within Photoshop.","Programmatically transformed design output into the foundation of an iPhone application.","Built the plugin in pure JavaScript against Adobe’s Photoshop framework."]', '["Adobe Photoshop Cloud Edition","JavaScript and Adobe extension APIs","Layer slicing and app-scaffolding automation"]', NULL, NULL, NULL, 1, 0, 1);
INSERT INTO projects (id, sort_order, title, eyebrow, summary, story_html, role, year, stack_json, signal, accent, category, status, highlights_json, scope, ownership_json, systems_json, note, source_label, source_url, published, featured, version) VALUES ('hubster', '15', 'Hubster', 'Streaming availability guide', 'A web product for discovering where a film or series could be streamed across different media services.', '', 'Product Engineer', 'Web archive', '["HTML5","CSS3","JavaScript","Bootstrap"]', 'HUB', 'acid', 'SaaS', 'Shipped web product', '["Unified fragmented streaming availability into a single browse experience."]', 'An early web product for answering a simple discovery question: where can a specific title be streamed?', '["Designed a browse experience that brought fragmented streaming availability into one place.","Built the product with the straightforward front-end stack of its era.","Focused on reducing the hunt across multiple media services."]', '["HTML5, CSS3, and JavaScript","Bootstrap responsive UI","Streaming availability browsing"]', NULL, NULL, NULL, 1, 0, 1);
INSERT INTO projects (id, sort_order, title, eyebrow, summary, story_html, role, year, stack_json, signal, accent, category, status, highlights_json, scope, ownership_json, systems_json, note, source_label, source_url, published, featured, version) VALUES ('dm-auto-leasing', '16', 'D&M Auto Leasing', 'Native leasing application', 'A native Android experience for a major auto-leasing business, released through the app store.', '', 'Android Engineer', 'Mobile archive', '["Java","Android Studio"]', 'DMA', 'amber', 'Mobile', 'Shipped mobile app', '["Designed and delivered as a native Android application."]', 'A native Android application for a Texas auto-leasing company, released through the Android app store at the time.', '["Designed and delivered the mobile application as a native Android product.","Worked in Java and Android Studio for the app-store release.","Built for a leasing business with a customer-facing vehicle workflow."]', '["Java and Android Studio","Native Android application delivery","App-store release lifecycle"]', 'The original Android app is no longer listed on Google Play. D&M’s current leasing website is linked as present-day company context.', 'View current D&M Leasing context', 'https://www.dmautoleasing.com/', 1, 0, 1);
INSERT INTO project_media (id, project_id, kind, url, caption, alt_text, sort_order, autoplay, preload) VALUES ('dm-auto-leasing-image-1', 'dm-auto-leasing', 'image', '/projects/dm-leasing/logo.webp', 'D&M Leasing brand mark', 'D&M Leasing brand mark', 0, 0, 'auto');
